func TestEnumFeedChangeStatus(t *testing.T) {
	t.Run("NewFromString_active", func(t *testing.T) {
		t.Parallel()
		val, err := NewFeedChangeStatusFromString("active")
		assert.NoError(t, err, "valid enum value should not return error")
		assert.Equal(t, FeedChangeStatus("active"), val, "enum value should match expected wire value")
	})

	t.Run("NewFromString_paused", func(t *testing.T) {
		t.Parallel()
		val, err := NewFeedChangeStatusFromString("paused")
		assert.NoError(t, err, "valid enum value should not return error")
		assert.Equal(t, FeedChangeStatus("paused"), val, "enum value should match expected wire value")
	})

	t.Run("NewFromString_Invalid", func(t *testing.T) {
		_, err := NewFeedChangeStatusFromString("invalid_value_that_does_not_exist")
		assert.Error(t, err)
	})

	t.Run("Ptr", func(t *testing.T) {
		val, err := NewFeedChangeStatusFromString("active")
		assert.NoError(t, err)
		ptr := val.Ptr()
		assert.NotNil(t, ptr)
		assert.Equal(t, val, *ptr)
	})
}
